def _compute_category(value: float, threshold: float) -> str:
    """Determine boundary category deterministically. v7.0: uses epsilon=0.005 for float tolerance."""
    epsilon = 0.005
    if value < threshold - epsilon:
        return "BELOW"
    elif value > threshold + epsilon:
        return "ABOVE"
    return "AT"

def _opa_eval(rego_file: str, rule: str, value: float, threshold: float) -> str:
    """Evaluate a boundary rule via OPA, falling back to deterministic calculation."""
    input_data = {"input": {"value": value, "threshold": threshold}}
    input_json = json.dumps(input_data)
    for pkg in ["jdg", "tax", "sc"]:
        candidate = POLICIES_DIR / pkg / rego_file
        if candidate.exists():
            data_path = str(candidate)
            break
    else:
        return _compute_category(value, threshold)
    try:
        result = subprocess.run(
            [OPA_BIN, "eval", "--data", data_path, "--input", "/dev/stdin", "data"],
            input=input_json, capture_output=True, text=True, timeout=5,
        )
        if result.returncode == 0 and result.stdout.strip():
            data = json.loads(result.stdout.strip())
            for expr in (data.get("result") or []):
                for e in (expr.get("expressions") if isinstance(expr, dict) else []):
                    val = e.get("value", "")
                    if isinstance(val, str) and val in ("BELOW", "AT", "ABOVE"):
                        return val
    except (subprocess.TimeoutExpired, FileNotFoundError, json.JSONDecodeError):
        pass
    return _compute_category(value, threshold)


